svg.metadata:
flowchart TB
  A["Read flags; prompt for missing selections"]
  B["Resolve template, features, name and destination"]
  C["Validate selections and directory; render templates"]
  D{"Install dependencies selected?"}
  E["Run package manager; inspect exit outcome"]
  F["Review generated project; prepare settings and services"]
  X["Report failure; inspect the written directory"]
  A --> B
  B --> C
  C --> D
  D -->|"yes"| E
  D -->|"no"| F
  E -->|"success"| F
  E -->|"failure"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class F good;
  class X stop;
